-- Run once in Supabase SQL Editor. Email/password auth is private; public identity is username.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(username ~ '^[a-z0-9_]{3,24}$'),display_name text not null default '',avatar_url text,top_book_year_id uuid,top_book_all_id uuid,created_at timestamptz default now());
create table public.user_books(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,google_id text not null,title text not null,author text not null default '',cover_url text,description text,status text not null default 'Want to Read' check(status in ('Want to Read','Reading','Finished')),finished_year integer,created_at timestamptz default now(),unique(user_id,google_id));
create table public.saved_words(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,word text not null,definition text not null,example text not null default '',created_at timestamptz default now());
create table public.friendships(id uuid primary key default gen_random_uuid(),requester_id uuid not null references public.profiles(id) on delete cascade,addressee_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted')),created_at timestamptz default now(),check(requester_id<>addressee_id),unique(requester_id,addressee_id));
create unique index friendships_pair_unique on public.friendships(least(requester_id,addressee_id),greatest(requester_id,addressee_id));
alter table public.profiles add constraint top_book_year_fk foreign key(top_book_year_id) references public.user_books(id) on delete set null;
alter table public.profiles add constraint top_book_all_fk foreign key(top_book_all_id) references public.user_books(id) on delete set null;
create function public.is_friend(other_id uuid) returns boolean language sql security definer set search_path='' stable as $$select exists(select 1 from public.friendships where status='accepted' and ((requester_id=auth.uid() and addressee_id=other_id) or (addressee_id=auth.uid() and requester_id=other_id)))$$;
create function public.book_owned(book_id uuid,owner_id uuid) returns boolean language sql security definer set search_path='' stable as $$select exists(select 1 from public.user_books where id=book_id and user_id=owner_id)$$;
create function public.validate_profile_books() returns trigger language plpgsql security definer set search_path='' as $$begin if new.top_book_year_id is not null and not public.book_owned(new.top_book_year_id,new.id) then raise exception 'Top book must be in your library';end if;if new.top_book_all_id is not null and not public.book_owned(new.top_book_all_id,new.id) then raise exception 'Top book must be in your library';end if;return new;end$$;
create trigger validate_profile_books before insert or update on public.profiles for each row execute function public.validate_profile_books();
create function public.new_user_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,username,display_name) values(new.id,'reader_'||substr(replace(new.id::text,'-',''),1,16),'');return new;end$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_user_profile();
alter table public.profiles enable row level security;
alter table public.user_books enable row level security;
alter table public.saved_words enable row level security;
alter table public.friendships enable row level security;
create policy "Profiles visible to signed-in users" on public.profiles for select to authenticated using(true);
create policy "Edit own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "Read own or friends books" on public.user_books for select to authenticated using(user_id=auth.uid() or public.is_friend(user_id));
create policy "Add own books" on public.user_books for insert to authenticated with check(user_id=auth.uid());
create policy "Edit own books" on public.user_books for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "Delete own books" on public.user_books for delete to authenticated using(user_id=auth.uid());
create policy "Read own words" on public.saved_words for select to authenticated using(user_id=auth.uid());
create policy "Add own words" on public.saved_words for insert to authenticated with check(user_id=auth.uid());
create policy "Delete own words" on public.saved_words for delete to authenticated using(user_id=auth.uid());
create policy "See participating friendships" on public.friendships for select to authenticated using(requester_id=auth.uid() or addressee_id=auth.uid());
create policy "Request friendship" on public.friendships for insert to authenticated with check(requester_id=auth.uid() and status='pending');
create policy "Accept received friendship" on public.friendships for update to authenticated using(addressee_id=auth.uid() and status='pending') with check(addressee_id=auth.uid() and status='accepted');
create policy "Remove participating friendship" on public.friendships for delete to authenticated using(requester_id=auth.uid() or addressee_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('avatars','avatars',true,2097152,array['image/png','image/jpeg','image/webp']) on conflict(id) do nothing;
create policy "Avatar images publicly readable" on storage.objects for select using(bucket_id='avatars');
create policy "Users upload own avatars" on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "Users update own avatars" on storage.objects for update to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
